func effectiveRecords(records []store.ReleaseRecord, version, asOf string) map[string]*store.ReleaseRecord {
	effective := make(map[string]*store.ReleaseRecord)
	for i := range records {
		record := &records[i]
		if version != "" && record.Version != version {
			continue
