		columnRows, err := s.db.Query(`PRAGMA index_info(` + index.name + `)`)
		if err != nil {
			return false, err
		}
		match := true
		position := 0
		for columnRows.Next() {
			var seqno, cid int
			var name string
			if err := columnRows.Scan(&seqno, &cid, &name); err != nil {
				columnRows.Close()
				return false, err
			}
			if position < len(columns) && name != columns[position] {
				match = false
			}
			position++
		}
		columnRows.Close()
		if err := columnRows.Err(); err != nil {
			return false, err
		}
		if match && position >= len(columns) {
			return true, nil
		}
	}
	return false, nil
}"""

