// getPromotionChain associates all release facts of one batch across the
// requested ordered environments and returns per-node facts, per-segment
// diffs and an overall consistency conclusion. It is read-only.
func getPromotionChain(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := c.Param("batch")
		sequence, ok := parseEnvironmentSequence(c, c.Query("environments"))
		if !ok {
			return
		}
		if !validateChainRequest(c, deps, batchID, sequence) {
			return
		}
		records, ok := loadBatchRecords(c, deps, batchID)
		if !ok {
			return
		}
		view, problem := buildPromotionChain(batchID, sequence, records)
		if problem != nil {
			fail(c, http.StatusConflict, store.CodePromotionChainConflictV1, problem.Error())
			return
		}
		c.JSON(http.StatusOK, view)
	}
}

// getLocalPromotionDiff computes the segment diff between any two ordered
// nodes of one batch.
func getLocalPromotionDiff(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := c.Param("batch")
		left := strings.TrimSpace(c.Query("left"))
		right := strings.TrimSpace(c.Query("right"))
		if left == "" || right == "" {
			fail(c, http.StatusBadRequest, store.CodeInvalidRequest,
				"left and right query parameters are required")
			return
		}
		if left == right {
			fail(c, http.StatusBadRequest, store.CodeSameEnvironmentCompareV1,
				"cannot diff an environment with itself")
			return
		}
		sequence := []string{left, right}
		if !validateChainRequest(c, deps, batchID, sequence) {
			return
		}
		records, ok := loadBatchRecords(c, deps, batchID)
		if !ok {
			return
		}
		chain, problem := buildPromotionChain(batchID, sequence, records)
		if problem != nil {
			fail(c, http.StatusConflict, store.CodePromotionChainConflictV1, problem.Error())
			return
		}
		c.JSON(http.StatusOK, localDiffView{
			BatchID:     batchID,
			Left:        left,
			Right:       right,
			SegmentDiff: chain.SegmentDiffs[0],
		})
	}
}

// getChangeTrace locates where a change entry first entered the chain, which
// environments it passed through and the first environment missing it.
func getChangeTrace(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := c.Param("batch")
		changeID := c.Param("change_id")
		sequence, ok := parseEnvironmentSequence(c, c.Query("environments"))
		if !ok {
			return
		}
		if !validateChainRequest(c, deps, batchID, sequence) {
			return
		}
		records, ok := loadBatchRecords(c, deps, batchID)
		if !ok {
			return
		}
		if _, problem := buildPromotionChain(batchID, sequence, records); problem != nil {
			fail(c, http.StatusConflict, store.CodePromotionChainConflictV1, problem.Error())
			return
		}
		c.JSON(http.StatusOK, buildChangeTrace(batchID, changeID, sequence, records))
	}
}

// parseEnvironmentSequence splits the ordered environments parameter.
func parseEnvironmentSequence(c *gin.Context, raw string) ([]string, bool) {
	if strings.TrimSpace(raw) == "" {
		fail(c, http.StatusBadRequest, store.CodeInvalidRequest,
			"environments query parameter is required")
		return nil, false
	}
	parts := strings.Split(raw, ",")
	sequence := make([]string, 0, len(parts))
	for _, part := range parts {
		name := strings.TrimSpace(part)
		if name == "" {
			fail(c, http.StatusBadRequest, store.CodeInvalidRequest,
				"environments must be a comma-separated list of non-empty environment names")
			return nil, false
		}
		sequence = append(sequence, name)
	}
	return sequence, true
}

// validateChainRequest applies the deterministic request checks in order:
// duplicated sequence members, unknown environments, then batch existence.
func validateChainRequest(c *gin.Context, deps Dependencies, batchID string, sequence []string) bool {
	if duplicated := duplicatedEnvironments(sequence); len(duplicated) > 0 {
		fail(c, http.StatusBadRequest, store.CodeDuplicateEnvironmentChainV1,
			"duplicate environments in sequence: "+strings.Join(duplicated, ", "))
		return false
	}
	unknown := []string{}
	for _, name := range sequence {
		exists, err := deps.Store.TrackedEnvironmentExists(name)
		if err != nil {
			failStorage(c)
			return false
		}
		if !exists {
			unknown = append(unknown, name)
		}
	}
	if len(unknown) > 0 {
		fail(c, http.StatusBadRequest, store.CodeUnknownEnvironmentChainV1,
			"unknown environments in sequence: "+strings.Join(unknown, ", "))
		return false
	}
	exists, err := deps.Store.BatchExists(batchID)
	if err != nil {
		failStorage(c)
		return false
	}
	if !exists {
		fail(c, http.StatusNotFound, store.CodeReleaseBatchNotFoundV1,
			"no release batch with id "+batchID)
		return false
	}
	return true
}

func loadBatchRecords(c *gin.Context, deps Dependencies, batchID string) ([]store.ReleaseRecord, bool) {
	records, err := deps.Store.ListBatchReleaseRecords(batchID)
	if err != nil {
		failStorage(c)
		return nil, false
	}
	return records, true
}

// duplicatedEnvironments returns sequence members appearing more than once,
// in first-occurrence order and deduplicated.
func duplicatedEnvironments(sequence []string) []string {
	seen := map[string]bool{}
	duplicated := []string{}
	for _, name := range sequence {
		count := 0
		for _, candidate := range sequence {
			if candidate == name {
				count++
			}
		}
		if count > 1 && !seen[name] {
			seen[name] = true
			duplicated = append(duplicated, name)
		}
	}
	return duplicated
}

// orderProblem describes adjacent nodes whose stored facts do not establish
// the requested promotion order.
type orderProblem struct {
	nodes []string
}

func (p *orderProblem) Error() string {
	return "insufficient release facts to determine promotion order for environment nodes: " +
		strings.Join(p.nodes, ", ")
}

// buildPromotionChain groups batch records by requested environment, verifies
// adjacent ordering from stored facts and computes per-segment diffs.
func buildPromotionChain(batchID string, sequence []string, records []store.ReleaseRecord) (promotionChainView, *orderProblem) {
	nodes := make([]chainNodeView, 0, len(sequence))
	byEnv := map[string][]store.ReleaseRecord{}
	for _, name := range sequence {
		byEnv[name] = []store.ReleaseRecord{}
	}
	for i := range records {
		if _, wanted := byEnv[records[i].Environment]; wanted {
			byEnv[records[i].Environment] = append(byEnv[records[i].Environment], records[i])
		}
	}
	for _, name := range sequence {
		nodes = append(nodes, chainNodeView{
			Environment: name,
			Releases:    toChainReleases(byEnv[name]),
		})
	}

	segments := make([]segmentDiffView, 0, len(sequence)-1)
	problemNodes := []string{}
	problemSet := map[string]bool{}
	addProblemNode := func(name string) {
		if !problemSet[name] {
			problemSet[name] = true
			problemNodes = append(problemNodes, name)
		}
	}
	categories := map[string]bool{}
	consistent := true
	for i := 0; i+1 < len(sequence); i++ {
		from, to := sequence[i], sequence[i+1]
		if !orderedBefore(byEnv[from], byEnv[to]) {
			addProblemNode(from)
			addProblemNode(to)
		}
		segment := diffSegment(from, to, byEnv[from], byEnv[to])
		if !segment.Consistent {
			consistent = false
			for _, category := range segment.DiffCategories {
				categories[category] = true
			}
		}
		segments = append(segments, segment)
	}
	if len(problemNodes) > 0 {
		orderedNodes := make([]string, 0, len(problemNodes))
		for _, name := range sequence {
			if problemSet[name] {
				orderedNodes = append(orderedNodes, name)
			}
		}
		return promotionChainView{}, &orderProblem{nodes: orderedNodes}
	}
	categoryList := make([]string, 0, len(categories))
	for category := range categories {
		categoryList = append(categoryList, category)
	}
	slices.Sort(categoryList)
	return promotionChainView{
		BatchID:                 batchID,
		EnvironmentSequence:     sequence,
		Nodes:                   nodes,
		SegmentDiffs:            segments,
		Consistent:              consistent,
		InconsistencyCategories: categoryList,
	}, nil
}

func toChainReleases(records []store.ReleaseRecord) []chainReleaseView {
	views := make([]chainReleaseView, 0, len(records))
	for i := range records {
		views = append(views, chainReleaseView{
			ID:            records[i].PublicID,
			Version:       records[i].Version,
			GateStatus:    records[i].GateStatus,
			RollbackPoint: records[i].RollbackPoint,
			Changes:       toChangeEntryViews(records[i].Changes),
			RecordedAt:    records[i].RecordedAt,
		})
	}
	return views
}

func toChangeEntryViews(entries []store.ChangeEntry) []changeEntryView {
	views := make([]changeEntryView, 0, len(entries))
	for _, entry := range entries {
		views = append(views, changeEntryView(entry))
	}
	return views
}

// orderedBefore reports whether stored facts establish that every promoted
// release on from happened strictly before the matching release on to. A
// shared version with an earlier timestamp proves the order; without any
// shared version the full time windows must be strictly disjoint.
func orderedBefore(from, to []store.ReleaseRecord) bool {
	if len(from) == 0 || len(to) == 0 {
		return false
	}
	fromByVersion := map[string]store.ReleaseRecord{}
	toByVersion := map[string]store.ReleaseRecord{}
	for _, record := range from {
		fromByVersion[record.Version] = record
	}
	for _, record := range to {
		toByVersion[record.Version] = record
	}
	shared := 0
	for version, fromRecord := range fromByVersion {
		toRecord, present := toByVersion[version]
		if !present {
			continue
		}
		shared++
		if !(fromRecord.RecordedAt < toRecord.RecordedAt) {
			return false
		}
	}
	if shared > 0 {
		return true
	}
	latestFrom := from[0]
	for _, record := range from[1:] {
		if record.RecordedAt > latestFrom.RecordedAt {
			latestFrom = record
		}
	}
	earliestTo := to[0]
	for _, record := range to[1:] {
		if record.RecordedAt < earliestTo.RecordedAt {
			earliestTo = record
		}
	}
	return latestFrom.RecordedAt < earliestTo.RecordedAt
}

// nodeState is the aggregated effective state of one environment node within
// a batch: every released version and the last-seen content of each entry.
type nodeState struct {
	versions map[string]store.ReleaseRecord
	entries  map[string]store.ChangeEntry
}

func aggregateNode(records []store.ReleaseRecord) nodeState {
	state := nodeState{
		versions: map[string]store.ReleaseRecord{},
		entries:  map[string]store.ChangeEntry{},
	}
	for _, record := range records {
		state.versions[record.Version] = record
		for _, entry := range record.Changes {
			state.entries[entry.Title] = entry
		}
	}
	return state
}

