// queryPromotionChain answers GET /release-batches/:batch/chain. The
// environment sequence is supplied by the caller; stored facts only.
func queryPromotionChain(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := strings.TrimSpace(c.Param("batch"))
		sequence, ok := parseEnvironmentSequence(c)
		if !ok {
			return
		}
		if !validateSequenceEnvironments(c, deps, sequence) {
			return
		}
		records, ok := requireBatch(c, deps, batchID)
		if !ok {
			return
		}
		if !ensureOrderable(c, records, sequence) {
			return
		}
		c.JSON(http.StatusOK, buildPromotionChain(batchID, sequence, records))
	}
}

// queryLocalPromotionDiff answers GET /release-batches/:batch/diff?from&to.
func queryLocalPromotionDiff(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := strings.TrimSpace(c.Param("batch"))
		from := strings.TrimSpace(c.Query("from"))
		to := strings.TrimSpace(c.Query("to"))
		if from == "" || to == "" {
			fail(c, http.StatusBadRequest, store.CodeInvalidRequest,
				"from and to query parameters are required")
			return
		}
		if from == to {
			fail(c, http.StatusBadRequest, store.CodeSameEnvironmentCompareV1,
				"cannot diff an environment with itself")
			return
		}
		sequence := []string{from, to}
		if !validateSequenceEnvironments(c, deps, sequence) {
			return
		}
		records, ok := requireBatch(c, deps, batchID)
		if !ok {
			return
		}
		if !ensureOrderable(c, records, sequence) {
			return
		}
		chain := buildPromotionChain(batchID, sequence, records)
		c.JSON(http.StatusOK, localDiffView{BatchID: batchID, Segment: chain.SegmentDiffs[0]})
	}
}

// queryChangeTrace answers GET /release-batches/:batch/changes/:id/trace.
func queryChangeTrace(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := strings.TrimSpace(c.Param("batch"))
		changeID := strings.TrimSpace(c.Param("change_id"))
		sequence, ok := parseEnvironmentSequence(c)
		if !ok {
			return
		}
		if !validateSequenceEnvironments(c, deps, sequence) {
			return
		}
		records, ok := requireBatch(c, deps, batchID)
		if !ok {
			return
		}
		if !ensureOrderable(c, records, sequence) {
			return
		}
		c.JSON(http.StatusOK, buildChangeTrace(batchID, changeID, sequence, records))
	}
}

// parseEnvironmentSequence reads and validates the shape of the ordered
// environment sequence query parameter. Values are comma separated.
func parseEnvironmentSequence(c *gin.Context) ([]string, bool) {
	raw := strings.TrimSpace(c.Query("environments"))
	if raw == "" {
		fail(c, http.StatusBadRequest, store.CodeInvalidRequest,
			"environments query parameter is required")
		return nil, false
	}
	parts := strings.Split(raw, ",")
	sequence := make([]string, 0, len(parts))
	for _, part := range parts {
		env := strings.TrimSpace(part)
		if env == "" {
			fail(c, http.StatusBadRequest, store.CodeInvalidRequest,
				"environments must be a non-empty, comma-separated list")
			return nil, false
		}
		sequence = append(sequence, env)
	}
	return sequence, true
}

// validateSequenceEnvironments rejects duplicates and unknown environments
// before any batch fact is consulted. Duplicates win over unknowns so the
// error is deterministic when both problems are present.
func validateSequenceEnvironments(c *gin.Context, deps Dependencies, sequence []string) bool {
	seen := map[string]int{}
	duplicates := map[string]bool{}
	for _, env := range sequence {
		seen[env]++
		if seen[env] > 1 {
			duplicates[env] = true
		}
	}
	if len(duplicates) > 0 {
		keys := make([]string, 0, len(duplicates))
		for env := range duplicates {
			keys = append(keys, env)
		}
		sort.Strings(keys)
		fail(c, http.StatusBadRequest, store.CodeDuplicateEnvironmentChainV1,
			"environment sequence contains duplicate environments: "+strings.Join(keys, ", "))
		return false
	}
	var unknown []string
	for _, env := range sequence {
		exists, err := deps.Store.TrackedEnvironmentExists(env)
		if err != nil {
			failStorage(c)
			return false
		}
		if !exists {
			unknown = append(unknown, env)
		}
	}
	if len(unknown) > 0 {
		sort.Strings(unknown)
		fail(c, http.StatusBadRequest, store.CodeUnknownEnvironmentChainV1,
			"environment sequence contains unknown environments: "+strings.Join(unknown, ", "))
		return false
	}
	return true
}

// requireBatch loads every fact tagged with the batch. A batch with no facts
// is the single observable NotFound outcome for the chain endpoints.
func requireBatch(c *gin.Context, deps Dependencies, batchID string) ([]store.ReleaseRecord, bool) {
	exists, err := deps.Store.BatchExists(batchID)
	if err != nil {
		failStorage(c)
		return nil, false
	}
	if !exists {
		fail(c, http.StatusNotFound, store.CodeReleaseBatchNotFoundV1,
			"no release batch with id "+batchID)
		return nil, false
	}
	records, err := deps.Store.ListBatchReleaseRecords(batchID)
	if err != nil {
		failStorage(c)
		return nil, false
	}
	return records, true
}

// ensureOrderable verifies that stored facts determine a non-decreasing
// promotion order across each adjacent pair of requested nodes. Pairs whose
// order cannot be established produce one Conflict naming both endpoints.
func ensureOrderable(c *gin.Context, records []store.ReleaseRecord, sequence []string) bool {
	byEnv := indexRecordsByEnvironment(records)
	type pair struct{ from, to string }
	var undecidable []pair
	for i := 0; i+1 < len(sequence); i++ {
		from, to := sequence[i], sequence[i+1]
		if !orderEstablished(byEnv[from], byEnv[to]) {
			undecidable = append(undecidable, pair{from: from, to: to})
		}
	}
	if len(undecidable) == 0 {
		return true
	}
	sort.Slice(undecidable, func(i, j int) bool {
		if undecidable[i].from != undecidable[j].from {
			return undecidable[i].from < undecidable[j].from
		}
		return undecidable[i].to < undecidable[j].to
	})
	descriptions := make([]string, 0, len(undecidable))
	seen := map[string]bool{}
	for _, p := range undecidable {
		key := p.from + "->" + p.to
		if seen[key] {
			continue
		}
		seen[key] = true
		descriptions = append(descriptions, key)
	}
	fail(c, http.StatusConflict, store.CodePromotionChainConflictV1,
		"release facts do not determine environment order for nodes: "+strings.Join(descriptions, ", "))
	return false
}

// orderEstablished reports whether the from -> to promotion direction is
// evidenced by stored timestamps. Records are already chronological.
func orderEstablished(from, to []store.ReleaseRecord) bool {
	if len(from) == 0 || len(to) == 0 {
		return false
	}
	fromByVersion := map[string]store.ReleaseRecord{}
	for _, record := range from {
		fromByVersion[record.Version] = record
	}
	toByVersion := map[string]store.ReleaseRecord{}
	for _, record := range to {
		toByVersion[record.Version] = record
	}
	sharedEvidence := false
	for version, toRecord := range toByVersion {
		fromRecord, ok := fromByVersion[version]
		if !ok {
			continue
		}
		sharedEvidence = true
		if toRecord.RecordedAt < fromRecord.RecordedAt {
			return false
		}
	}
	if sharedEvidence {
		return true
	}
	// No shared version: the whole from window must precede the whole to window.
	fromLast := from[len(from)-1].RecordedAt
	toFirst := to[0].RecordedAt
	return toFirst >= fromLast
}

